	{ key = "aim_nomouse_min", cat = AI, type = "number", def = 10, min = 3, max = 45, dec = 0,
	  label = "No-mouse turn threshold (degrees per tick)", help = "" },
	{ key = "aim_nomouse_pts", cat = AI, type = "number", def = 1, min = 0.25, max = 10, dec = 2,
	  label = "Points per no-mouse turn", help = "" },
	{ key = "aim_enabled",  cat = AI, type = "bool", def = true,
