	{ key = "ballistics_enabled", cat = AI, type = "bool", def = true, label = "Validate bullet origins and directions", help = "Observe server-side bullet trajectories versus recorded commands; evidence only." },
	{ key = "ballistics_angle", cat = AI, type = "number", def = 12, min = 3, max = 60, dec = 0, label = "Bullet/command divergence (degrees)", help = "High thresholds recommended for scripted weapons and spread." },
	{ key = "ballistics_points", cat = AI, type = "number", def = 1, min = 0.1, max = 5, dec = 1, label = "Bullet mismatch points", help = "Only repeated mismatches are scored." },
	{ key = "movement_enabled", cat = "Movement", type = "bool", def = true, label = "Monitor movement anomalies", help = "Repeated impossible movement bursts, with exemptions for vehicles, noclip and server teleports." },
