Veltrix.SchemaByKey = {}
Veltrix.Config = Veltrix.Config or {}
for _, s in ipairs(Veltrix.Schema) do
	Veltrix.SchemaByKey[s.key] = s
	if Veltrix.Config[s.key] == nil then Veltrix.Config[s.key] = s.def end
end

function Veltrix.Cfg(key)
	return Veltrix.Config[key]
end
